 for(let i=0;i<56;i++)o+=rect(235+i*9,550,6,24,'gold',0);
 o+=text(550,610,'PCIe ×16','tiny');o+=action('peek:pcie','PCIe interface',rect(223,540,520,41,'plate',3)+Array.from({length:56},(_,i)=>rect(235+i*9,550,6,24,'gold',0)).join(''));
 for(let i=0;i<9;i++){o+=rect(795,152+i*32,38,23,'plate',3)+rect(848,152+i*32,23,23,'metal',3)+rect(890,152+i*32,28,23,'plate',2)}o+=action('peek:power','Power delivery',rect(778,130,166,338,'empty',6)+text(860,493,'POWER','tiny'));
 for(const [x,y] of [[407,145],[555,145],[307,264],[690,264],[407,430],[555,430]]){o+=action('memory','Explore GDDR6X memory',rect(x,y,112, 60,'plate',4)+dots(x+13,y+11,8,3,10)+text(x+56,y+49,'GDDR6X','micro'))}
